/* GENERATED by tools/split-map.js from film-engine/src/index.html: the functions only the stylebook page uses. Do not edit; edit the source or the tool. */


    async function loadStyleBook() {
        const grid = document.getElementById('styleBookGrid');
        if (!grid) return;
        grid.innerHTML = '<p class="text-sm text-muted">Loading…</p>';
        try {
            // With a project open you see its own entries plus the library;
            // without one, the library alone. The style book is usable before
            // any film exists, which is half the point of it being global.
            _styleBook = await api(state.currentProject
                ? '/projects/' + state.currentProject.id + '/style-book'
                : '/style-book');
            renderStyleBook();
        } catch (err) {
            grid.innerHTML = '<p class="text-sm">Could not load the style book: ' + esc(err.message) + '</p>';
        }
    }

    /** The facets an entry carries, as the tags a director searches by. */
    function styleBookTags(entry) {
        const c = entry.camera || {};
        const bits = [];
        if (c.shot_type) bits.push(esc(c.shot_type));
        if (c.lens) bits.push(esc(c.lens));
        if (c.movement && c.movement !== 'static') bits.push(esc(c.movement));
        if (c.sensor) bits.push(esc(c.sensor));
        if (c.aperture) bits.push('T' + esc(String(c.aperture)));
        if (c.height_m !== undefined) bits.push(esc(String(c.height_m)) + 'm');
        return bits.map(b => '<span class="tag">' + b + '</span>').join('');
    }

    /** The one note about what visuals are for, from the API, never a second literal. */
    function styleBookNoteInto(el) {
        if (el) el.textContent = (_styleBook && _styleBook.note) || '';
    }

    function renderStyleBook() {
        const grid = document.getElementById('styleBookGrid');
        if (!grid) return;
        const q = (document.getElementById('styleBookFilter')?.value || '').trim().toLowerCase();
        const entries = (_styleBook.entries || []).filter(e => !q
            || (e.name + ' ' + e.description + ' ' + e.tags + ' ' + JSON.stringify(e.camera || {}))
                .toLowerCase().includes(q));

        if (!entries.length) {
            grid.innerHTML = (_styleBook.entries || []).length
                ? '<p class="text-sm text-muted">Nothing matches that.</p>'
                : '<p class="text-sm text-muted">No shots yet. Add one when you see an angle you want '
                  + 'again &mdash; a name and a lens is enough to start.</p>';
            return;
        }

        grid.innerHTML = '<div class="entity-grid">' + entries.map(e => `
            <div class="entity-card">
                ${(e.media || []).length
                    ? `<img src="${API_BASE}/film/style-book/media/${esc(e.media[0].id)}/file"
                           alt="" style="width:100%;border-radius:6px;margin-bottom:8px;display:block;"
                           onerror="this.style.display='none'">`
                    : ''}
                <div class="flex-between">
                    <strong style="font-size:13px;">${esc(e.name)}</strong>
                    <span class="tag">${e.scope === 'library' ? 'library' : 'this film'}</span>
                </div>
                ${e.description ? `<p class="text-sm">${esc(e.description)}</p>` : ''}
                <div class="tag-row">${styleBookTags(e)}</div>
                ${e.tags ? `<p class="text-sm text-muted" style="margin-top:6px;">${esc(e.tags)}</p>` : ''}
                <div class="card-actions">
                    <button class="btn btn-secondary btn-sm" onclick="editStyleBookEntry('${esc(e.id)}')">Edit</button>
                    <button class="btn btn-danger btn-sm" onclick="deleteStyleBookEntry('${esc(e.id)}')">Delete</button>
                </div>
            </div>`).join('') + '</div>'
            + `<p class="text-sm text-muted" style="margin-top:12px;max-width:70ch;line-height:1.5;">${esc(_styleBook.note || '')}</p>`;
    }

    function newStyleBookEntry() { openStyleBookModal(null); }

    function editStyleBookEntry(id) {
        openStyleBookModal((_styleBook.entries || []).find(e => e.id === id) || null);
    }

    /**
     * The editor.
     *
     * Every camera facet is a control, and each says what it means rather than
     * assuming the reader knows — height in particular, because it is the one
     * that makes a low-angle sayable and the one nobody thinks to fill in.
     */
    function openStyleBookModal(entry) {
        styleBookNoteInto(document.getElementById('styleBookMediaNote_'));
        const c = (entry && entry.camera) || {};
        document.getElementById('styleBookModalTitle').textContent = entry ? 'Edit shot' : 'New shot';
        document.getElementById('styleBookEditId').value = entry ? entry.id : '';
        const m = document.getElementById('styleBookModal');
        const set = (field, value) => {
            const el = m.querySelector(`[data-field="${field}"]`);
            if (el) el.value = value === undefined || value === null ? '' : value;
        };
        set('name', entry && entry.name);
        set('description', entry && entry.description);
        set('tags', entry && entry.tags);
        set('scope', entry ? entry.scope : 'library');
        for (const f of ['shot_type', 'movement', 'lens', 'sensor', 'aperture', 'height_m', 'focus_distance_m', 'note']) {
            set(f, c[f]);
        }

        /*
         * Visuals need something to attach to. On a NEW entry the section is
         * hidden and appears after the first save — an upload into an entry
         * that is then cancelled would leave a file with no owner.
         */
        /*
         * ALWAYS SHOWN.
         *
         * Hiding it until the entry was saved meant pressing "+ Shot" offered
         * no way to add a picture at all — which reads as the feature being
         * missing, and was reported as exactly that. The invariant it was
         * protecting is real (an upload needs an owner, or the file is
         * orphaned by a cancel), so Add visual SAVES THE ENTRY FIRST rather
         * than making the director do it.
         */
        const mediaSection = document.getElementById('styleBookMediaSection');
        const addBtn = document.getElementById('styleBookAddMediaBtn');
        mediaSection.style.display = '';
        addBtn.onclick = () => addStyleBookMedia(entry ? entry.id : null);
        if (entry) refreshStyleBookMedia(entry.id);
        else {
            document.getElementById('styleBookMediaList').innerHTML =
                '<p class="text-sm text-muted">Add one below &mdash; the shot is saved automatically '
                + 'when you do.</p>';
        }
        showModal('styleBookModal');
    }

    /**
     * @param {{keepOpen?: boolean}} [opts] keepOpen leaves the modal up and
     *        returns the saved entry, so a visual can be attached to a shot
     *        that did not exist a moment ago.
     */
    async function saveStyleBookEntry(opts) {
        const keepOpen = !!(opts && opts.keepOpen);
        const m = document.getElementById('styleBookModal');
        const get = f => (m.querySelector(`[data-field="${f}"]`)?.value || '').trim();
        const num = f => { const raw = get(f); return raw === '' ? undefined : Number(raw); };

        const camera = {};
        for (const f of ['shot_type', 'movement', 'lens', 'sensor', 'note']) {
            const val = get(f); if (val) camera[f] = val;
        }
        for (const f of ['aperture', 'height_m', 'focus_distance_m']) {
            const n = num(f); if (Number.isFinite(n)) camera[f] = n;
        }

        const body = {
            name: get('name'), description: get('description'),
            tags: get('tags'), scope: get('scope') || 'library', camera,
        };
        if (!body.name) { setStatus('Give the shot a name first'); return null; }

        const id = document.getElementById('styleBookEditId').value;
        try {
            const r = id
                ? await api('/style-book/' + id, { method: 'PUT', body: JSON.stringify(body) })
                : await api((state.currentProject ? '/projects/' + state.currentProject.id : '') + '/style-book',
                    { method: 'POST', body: JSON.stringify(body) });
            if (!keepOpen) closeModal('styleBookModal');
            setStatus('Style book saved');
            loadStyleBook();
            return (r && r.entry) || { id };
        } catch (err) { setStatus('Error: ' + err.message); return null; }
    }

    /**
     * Attach a visual to a style-book entry — a file or a link.
     *
     * Both, because a reference lives in both places: a frame grab on this
     * machine, and a YouTube clip that demonstrates a move a still cannot. The
     * two are stored differently (bytes on disk versus a URL) and rendered
     * differently, so the control offers both plainly rather than making the
     * director work out which field applies.
     */
    async function addStyleBookMedia(entryId) {
        /*
         * An unsaved entry is saved first, here, rather than refusing.
         * "Save it, then re-open it, then attach" is three steps to do one
         * thing, and the reason for the constraint — a file needs an owner —
         * is satisfied just as well by creating the owner.
         */
        if (!entryId) {
            const saved = await saveStyleBookEntry({ keepOpen: true });
            if (!saved) return;                 // no name yet, or the save failed
            entryId = saved.id;
            document.getElementById('styleBookEditId').value = saved.id;
            document.getElementById('styleBookAddMediaBtn').onclick = () => addStyleBookMedia(saved.id);
        }
        const file = document.getElementById('styleBookMediaFile');
        const urlBox = document.getElementById('styleBookMediaUrl');
        const note = (document.getElementById('styleBookMediaNote')?.value || '').trim();
        const url = (urlBox?.value || '').trim();

        try {
            if (file && file.files && file.files[0]) {
                const f = file.files[0];
                const data = await new Promise((resolve, reject) => {
                    const r = new FileReader();
                    r.onload = () => resolve(r.result);
                    r.onerror = () => reject(new Error('could not read that file'));
                    r.readAsDataURL(f);
                });
                checkUploadSize(f, `/style-book/${entryId}/media`);
                await api(`/style-book/${entryId}/media`, {
                    method: 'POST',
                    body: JSON.stringify({
                        data, name: f.name, note,
                        media_kind: /^video\//.test(f.type) ? 'video' : 'image',
                    }),
                });
                file.value = '';
            } else if (url) {
                await api(`/style-book/${entryId}/media`, {
                    method: 'POST', body: JSON.stringify({ source_url: url, note }),
                });
                urlBox.value = '';
            } else {
                setStatus('Choose a file or paste a link first');
                return;
            }
            if (document.getElementById('styleBookMediaNote')) {
                document.getElementById('styleBookMediaNote').value = '';
            }
            setStatus('Visual added');
            await refreshStyleBookMedia(entryId);
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    async function removeStyleBookMedia(entryId, mediaId) {
        if (!confirm('Remove this visual from the entry?')) return;
        try {
            await api(`/style-book/media/${mediaId}`, { method: 'DELETE' });
            await refreshStyleBookMedia(entryId);
            loadStyleBook();
        } catch (err) { setStatus('Error: ' + err.message); }
    }

    /** Render one visual as what it actually is. */
    function styleBookMediaTile(entryId, m) {
        const src = m.url && m.url.startsWith('/film/') ? API_BASE + m.url : m.url;
        let body;
        if (m.embed_url) {
            // A move is what a clip is FOR — an embedded player shows it where
            // a thumbnail would only prove a link exists.
            body = `<iframe src="${esc(m.embed_url)}" allowfullscreen loading="lazy"
                        style="width:100%;aspect-ratio:16/9;border:0;border-radius:6px;display:block;"></iframe>`;
        } else if (m.link_kind === 'video' || m.media_kind === 'video') {
            body = `<video src="${esc(src)}" controls preload="metadata"
                        style="width:100%;border-radius:6px;display:block;"></video>`;
        } else if (m.link_kind === 'link') {
            body = `<a href="${esc(src)}" target="_blank" rel="noopener"
                       class="text-sm" style="display:block;padding:18px 10px;text-align:center;">
                       ${esc(src.slice(0, 60))}&hellip;</a>`;
        } else {
            body = `<img src="${esc(src)}" alt="" loading="lazy"
                        style="width:100%;border-radius:6px;display:block;cursor:zoom-in;"
                        onclick="openPlateViewer('${esc(src)}', ${jsAttr(m.note || 'Reference')})"
                        onerror="this.replaceWith(Object.assign(document.createElement('p'),{className:'text-sm text-muted',textContent:'This picture could not be loaded.'}))">`;
        }
        return `<div style="border:1px solid var(--gl-border-subtle);border-radius:8px;padding:8px;min-width:0;">
            ${body}
            ${m.note ? `<p class="text-sm" style="margin-top:6px;">${esc(m.note)}</p>` : ''}
            <div class="card-actions">
                <button class="btn btn-danger btn-sm"
                        onclick="removeStyleBookMedia('${esc(entryId)}','${esc(m.id)}')">Remove</button>
            </div>
        </div>`;
    }

    async function refreshStyleBookMedia(entryId) {
        const host = document.getElementById('styleBookMediaList');
        if (!host) return;
        try {
            const r = await api(`/style-book/${entryId}`);
            const media = r.entry.media || [];
            host.innerHTML = media.length
                ? `<div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px;">`
                  + media.map(m => styleBookMediaTile(entryId, m)).join('') + '</div>'
                : '<p class="text-sm text-muted">No visuals yet.</p>';
        } catch (err) {
            host.innerHTML = `<p class="text-sm text-muted">Could not load visuals: ${esc(err.message)}</p>`;
        }
    }

    async function deleteStyleBookEntry(id) {
        const e = (_styleBook.entries || []).find(x => x.id === id);
        if (!confirm(`Delete "${e ? e.name : 'this shot'}"?\n\nIt goes from every project.`)) return;
        try {
            await api('/style-book/' + id, { method: 'DELETE' });
            setStatus('Deleted');
            loadStyleBook();
        } catch (err) { setStatus('Error: ' + err.message); }
    }
